def scan_code_patterns(project_path: str) -> Dict[str, Any]:
    """
    Validate dangerous code patterns (OWASP A05).
    Checks: Injection risks, XSS, unsafe deserialization.
    """
    results = {
        "tool": "pattern_scanner",
        "findings": [],
        "status": "[OK] No dangerous patterns",
        "scanned_files": 0,
        "by_category": {}
    }
    
    for root, dirs, files in os.walk(project_path):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        
        for file in files:
            ext = Path(file).suffix.lower()
            if ext not in CODE_EXTENSIONS:
                continue
                
            filepath = Path(root) / file
            results["scanned_files"] += 1
            
            try:
                with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                    lines = f.readlines()
                    
                    for line_num, line in enumerate(lines, 1):
                        for pattern, name, severity, category in DANGEROUS_PATTERNS:
                            if re.search(pattern, line, re.IGNORECASE):
                                results["findings"].append({
                                    "file": str(filepath.relative_to(project_path)),
                                    "line": line_num,
                                    "pattern": name,
                                    "severity": severity,
                                    "category": category,
                                    "snippet": line.strip()[:80]
                                })
                                results["by_category"][category] = results["by_category"].get(category, 0) + 1
                                
            except Exception:
                pass
    
    critical_count = sum(1 for f in results["findings"] if f["severity"] == "critical")
    high_count = sum(1 for f in results["findings"] if f["severity"] == "high")
    
    if critical_count > 0:
        results["status"] = f"[!!] CRITICAL: {critical_count} dangerous patterns"
    elif high_count > 0:
        results["status"] = f"[!] HIGH: {high_count} risky patterns"
    elif results["findings"]:
        results["status"] = "[?] Some patterns need review"
    
    # Limit findings
    results["findings"] = results["findings"][:20]
    
    return results

def scan_configuration(project_path: str) -> Dict[str, Any]:
    """
    Validate security configuration (OWASP A02).
    Checks: Security headers, CORS, debug modes.
    """
    results = {
        "tool": "config_scanner",
        "findings": [],
        "status": "[OK] Configuration secure",
        "checks": {}
    }
    
    # Check common config files for issues
    config_issues = [
        (r'"DEBUG"\s*:\s*true', "Debug mode enabled", "high"),
        (r'debug\s*=\s*True', "Debug mode enabled", "high"),
        (r'NODE_ENV.*development', "Development mode in config", "medium"),
        (r'"CORS_ALLOW_ALL".*true', "CORS allow all origins", "high"),
        (r'"Access-Control-Allow-Origin".*\*', "CORS wildcard", "high"),
        (r'allowCredentials.*true.*origin.*\*', "Dangerous CORS combo", "critical"),
    ]
    
    for root, dirs, files in os.walk(project_path):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        
        for file in files:
            ext = Path(file).suffix.lower()
            if ext not in CONFIG_EXTENSIONS and file not in ['next.config.js', 'webpack.config.js', '.eslintrc.js']:
                continue
                
            filepath = Path(root) / file
            
            try:
                with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
                    
                    for pattern, issue, severity in config_issues:
                        if re.search(pattern, content, re.IGNORECASE):
                            results["findings"].append({
                                "file": str(filepath.relative_to(project_path)),
                                "issue": issue,
                                "severity": severity
                            })
                            
            except Exception:
                pass
    
    # Check for security header configurations
    header_files = ["next.config.js", "next.config.mjs", "middleware.ts", "nginx.conf"]
    for hf in header_files:
        hf_path = Path(project_path) / hf
        if hf_path.exists():
            results["checks"]["security_headers_config"] = True
            break
    else:
        results["checks"]["security_headers_config"] = False
        results["findings"].append({
            "issue": "No security headers configuration found",
            "severity": "medium",
            "recommendation": "Configure CSP, HSTS, X-Frame-Options headers"
        })
    
    if any(f["severity"] == "critical" for f in results["findings"]):
        results["status"] = "[!!] CRITICAL: Configuration issues"
    elif any(f["severity"] == "high" for f in results["findings"]):
        results["status"] = "[!] HIGH: Configuration review needed"
    elif results["findings"]:
        results["status"] = "[?] Minor configuration issues"
    
    return results

def scan_dependencies(project_path: str) -> Dict[str, Any]:
    """
    Validate supply chain security (OWASP A03).
    Checks: npm audit, lock file presence, dependency age.
    """
    results = {"tool": "dependency_scanner", "findings": [], "status": "[OK] Secure"}
    
    # Check for lock files
    lock_files = {
        "npm": ["package-lock.json", "npm-shrinkwrap.json"],
        "yarn": ["yarn.lock"],
        "pnpm": ["pnpm-lock.yaml"],
        "pip": ["requirements.txt", "Pipfile.lock", "poetry.lock"],
    }
    
    found_locks = []
    missing_locks = []
    
    for manager, files in lock_files.items():
        pkg_file = "package.json" if manager in ["npm", "yarn", "pnpm"] else "setup.py"
        pkg_path = Path(project_path) / pkg_file
        
        if pkg_path.exists() or (manager == "pip" and (Path(project_path) / "requirements.txt").exists()):
            has_lock = any((Path(project_path) / f).exists() for f in files)
            if has_lock:
                found_locks.append(manager)
            else:
                missing_locks.append(manager)
                results["findings"].append({
                    "type": "Missing Lock File",
                    "severity": "high",
                    "message": f"{manager}: No lock file found. Supply chain integrity at risk."
                })
    
    # Run npm audit if applicable
    if (Path(project_path) / "package.json").exists():
        try:
            result = subprocess.run(
                ["npm", "audit", "--json"],
                cwd=project_path,
                capture_output=True,
                text=True,
                timeout=60
            )
            
            try:
                audit_data = json.loads(result.stdout)
                vulnerabilities = audit_data.get("vulnerabilities", {})
                
                severity_count = {"critical": 0, "high": 0, "moderate": 0, "low": 0}
                for vuln in vulnerabilities.values():
                    sev = vuln.get("severity", "low").lower()
                    if sev in severity_count:
                        severity_count[sev] += 1
                
                if severity_count["critical"] > 0:
                    results["status"] = "[!!] Critical vulnerabilities"
                    results["findings"].append({
                        "type": "npm audit",
                        "severity": "critical",
                        "message": f"{severity_count['critical']} critical vulnerabilities in dependencies"
                    })
                elif severity_count["high"] > 0:
                    results["status"] = "[!] High vulnerabilities"
                    results["findings"].append({
                        "type": "npm audit",
                        "severity": "high",
                        "message": f"{severity_count['high']} high severity vulnerabilities"
                    })
                
                results["npm_audit"] = severity_count
                
            except json.JSONDecodeError:
                pass
                
        except (FileNotFoundError, subprocess.TimeoutExpired):
            pass
    
    if not results["findings"]:
        results["status"] = "[OK] Supply chain checks passed"
    
    return results

def scan_secrets(project_path: str) -> Dict[str, Any]:
    """
    Validate no hardcoded secrets (OWASP A04).
    Checks: API keys, tokens, passwords, cloud credentials.
    """
    results = {
        "tool": "secret_scanner",
        "findings": [],
        "status": "[OK] No secrets detected",
        "scanned_files": 0,
        "by_severity": {"critical": 0, "high": 0, "medium": 0}
    }
    
    for root, dirs, files in os.walk(project_path):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        
        for file in files:
            ext = Path(file).suffix.lower()
            if ext not in CODE_EXTENSIONS and ext not in CONFIG_EXTENSIONS:
                continue
                
            filepath = Path(root) / file
            results["scanned_files"] += 1
            
            try:
                with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
                    
                    for pattern, secret_type, severity in SECRET_PATTERNS:
                        matches = re.findall(pattern, content, re.IGNORECASE)
                        if matches:
                            results["findings"].append({
                                "file": str(filepath.relative_to(project_path)),
                                "type": secret_type,
                                "severity": severity,
                                "count": len(matches)
                            })
                            results["by_severity"][severity] += len(matches)
                            
            except Exception:
                pass
    
    if results["by_severity"]["critical"] > 0:
        results["status"] = "[!!] CRITICAL: Secrets exposed!"
    elif results["by_severity"]["high"] > 0:
        results["status"] = "[!] HIGH: Secrets found"
    elif sum(results["by_severity"].values()) > 0:
        results["status"] = "[?] Potential secrets detected"
    
    # Limit findings for output
    results["findings"] = results["findings"][:15]
    
    return results

def run_accessibility_check(url: str) -> dict:
    """Run basic accessibility check."""
    if not PLAYWRIGHT_AVAILABLE:
        return {"error": "Playwright not installed"}
    
    result = {"url": url, "accessibility": {}}
    
    try:
        with sync_playwright() as p:
            browser = p.chromium.launch(headless=True)
            page = browser.new_page()
            page.goto(url, wait_until="networkidle", timeout=30000)
            
            # Basic a11y checks
            result["accessibility"] = {
                "images_with_alt": page.locator("img[alt]").count(),
                "images_without_alt": page.locator("img:not([alt])").count(),
                "buttons_with_label": page.locator("button[aria-label], button:has-text('')").count(),
                "links_with_text": page.locator("a:has-text('')").count(),
                "form_labels": page.locator("label").count(),
                "headings": {
                    "h1": page.locator("h1").count(),
                    "h2": page.locator("h2").count(),
                    "h3": page.locator("h3").count()
                }
            }
            
            browser.close()
            result["status"] = "success"
            
    except Exception as e:
        result["status"] = "error"
        result["error"] = str(e)
    
    return result

def plan(
    path: Path = typer.Argument(Path("."), help="Root directory to scan."),  # noqa: B008
    max_file_size: int = typer.Option(
        2_000_000, "--max-file-size", help="Skip files larger than this, in bytes."
    ),
    verbose: bool = typer.Option(False, "-v", "--verbose", help="Print per-file warnings."),
) -> None:
    """Compute a bottom-up, staleness-aware doc-generation plan and write docs-plan.json."""
    root = path.resolve()

    if not root.exists():
        err_console.print(f"[red]error:[/red] path does not exist: {root}")
        raise typer.Exit(code=1)
    if not root.is_dir():
        err_console.print(f"[red]error:[/red] not a directory: {root}")
        raise typer.Exit(code=1)

    try:
        ensure_buddhi_dirs(root)
        ensure_docs_dir(root)
    except BuddhiFsError as exc:
        err_console.print(f"[red]error:[/red] {exc}")
        raise typer.Exit(code=1) from exc

    result = run_pipeline(root, max_file_size=max_file_size)
    if verbose:
        for warning in result.build_ctx.warnings:
            err_console.print(f"[yellow]warning:[/yellow] {warning}")

    entries = build_docs_plan(result.build_ctx.graph, root)
    plan_path = root / ".buddhi" / "docs-plan.json"
    try:
        plan_path.write_text(json.dumps(plan_to_json(entries), indent=2), encoding="utf-8")
    except OSError as exc:
        err_console.print(f"[red]error:[/red] failed writing {plan_path}: {exc}")
        raise typer.Exit(code=1) from exc

    stale = sum(1 for e in entries if e.needs_generation)
    console.print(f"[bold green]done[/bold green] planned docs for {root}")
    console.print(f"  entries: {len(entries)} total, {stale} need (re)generation")
    console.print(f"  wrote: {plan_path}")

def _load_gitignore_spec(root: Path) -> pathspec.PathSpec | None:
    gitignore_path = root / ".gitignore"
    if not gitignore_path.is_file():
        return None
    try:
        lines = gitignore_path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return None
    return pathspec.PathSpec.from_lines("gitignore", lines)

def read_existing_content_hash(doc_abs_path: Path) -> str | None:
    """Extract `sources[0].content_hash` from an existing OKF doc's frontmatter, if any."""
    if not doc_abs_path.is_file():
        return None
    try:
        text = doc_abs_path.read_text(encoding="utf-8")
    except OSError:
        return None

    match = _FRONTMATTER_RE.match(text)
    frontmatter = match.group(1) if match else text
    hash_match = _CONTENT_HASH_RE.search(frontmatter)
    return hash_match.group(1) if hash_match else None

def topological_doc_order(graph: CodeGraph) -> list[GraphNode]:
    """Return clusterable nodes ordered so every callee/base precedes its callers.

    Cycles (mutual/recursive calls) can't be strictly ordered; nodes involved
    in a cycle are appended in a stable (id-sorted) order once every node
    outside the cycle that can be resolved has been. This never raises on
    cyclic graphs — RepoAgent's own DAG assumption doesn't hold for real
    codebases with recursion, so we degrade gracefully instead of crashing.
    """
    nodes = {n.id: n for n in graph.nodes.values() if n.kind in _CLUSTERABLE_KINDS}
    if not nodes:
        return []

    # dependency edges: source depends on target (target must be documented first)
    depends_on: dict[str, set[str]] = {node_id: set() for node_id in nodes}
    dependents: dict[str, set[str]] = {node_id: set() for node_id in nodes}
    for edge in graph.edges:
        if edge.kind not in _ORDER_EDGE_KINDS:
            continue
        if edge.source not in nodes or edge.target not in nodes:
            continue
        if edge.source == edge.target:
            continue
        depends_on[edge.source].add(edge.target)
        dependents[edge.target].add(edge.source)

    remaining_deps = {node_id: set(deps) for node_id, deps in depends_on.items()}
    ready = sorted(node_id for node_id, deps in remaining_deps.items() if not deps)
    ordered: list[str] = []
    seen: set[str] = set()

    while ready:
        ready.sort()
        node_id = ready.pop(0)
        if node_id in seen:
            continue
        seen.add(node_id)
        ordered.append(node_id)
        for dependent in sorted(dependents.get(node_id, ())):
            if dependent in seen:
                continue
            remaining_deps[dependent].discard(node_id)
            if not remaining_deps[dependent]:
                ready.append(dependent)

    # Anything left is part of a cycle; append deterministically.
    leftover = sorted(node_id for node_id in nodes if node_id not in seen)
    ordered.extend(leftover)

    return [nodes[node_id] for node_id in ordered]

def _add_directory_nodes(ctx: BuildContext, walk_result: WalkResult) -> None:
    for dir_rel in sorted(walk_result.directories):
        parent_rel = Path(dir_rel).parent.as_posix()
        parent_id = dir_node_id(parent_rel) if parent_rel != "." else None
        node = ctx.graph.add_node(
            GraphNode(
                id=dir_node_id(dir_rel),
                kind=DIRECTORY,
                name=Path(dir_rel).name,
                qualified_name=dir_rel,
                parent_id=parent_id,
            )
        )
        if parent_id:
            ctx.graph.add_edge(GraphEdge(source=parent_id, target=node.id, kind=CONTAINS))

def _make_snippet(source: bytes, start_byte: int, end_byte: int) -> str:
    text = source[start_byte:end_byte].decode("utf-8", errors="replace")
    if len(text) > _SNIPPET_MAX_CHARS:
        return text[:_SNIPPET_MAX_CHARS] + "\n… (truncated)"
    return text

def assign_communities(graph: CodeGraph) -> int:
    """Assign `community_id` to class/function/method nodes in place.

    Returns the number of distinct communities found, or 0 if clustering was
    skipped (igraph unavailable, or fewer than 2 clusterable nodes).
    """
    try:
        import igraph as ig  # type: ignore[import-untyped]
    except ImportError:
        return 0

    node_ids = [n.id for n in graph.nodes.values() if n.kind in _CLUSTERABLE_KINDS]
    if len(node_ids) < 2:
        return 0

    index = {node_id: i for i, node_id in enumerate(node_ids)}
    node_set = set(node_ids)

    edges: list[tuple[int, int]] = []
    weights: list[float] = []
    for edge in graph.edges:
        weight = _EDGE_WEIGHTS.get(edge.kind)
        if weight is None:
            continue
        if edge.source not in node_set or edge.target not in node_set:
            continue
        edges.append((index[edge.source], index[edge.target]))
        weights.append(weight)

    g = ig.Graph(n=len(node_ids), directed=True)
    if edges:
        g.add_edges(edges)
        g.es["weight"] = weights

    partition = g.community_leiden(
        objective_function="modularity",
        weights="weight" if edges else None,
    )

    for node_id, community_id in zip(node_ids, partition.membership, strict=True):
        graph.nodes[node_id].community_id = community_id

    return len(set(partition.membership))

def _clean_import_text(text: str) -> str:
    text = text.strip()
    if len(text) >= 2 and text[0] in "\"'" and text[-1] == text[0]:
        text = text[1:-1]
    return text

def run_pipeline(root: Path, max_file_size: int = 2_000_000) -> PipelineResult:
    """Walk `root`, build the code graph, resolve edges, and cluster it."""
    lang_status = available_languages()
    avail = {lang for lang, err in lang_status.items() if err is None}
    language_warnings = {lang: err for lang, err in lang_status.items() if err is not None}

    walk_result = walk(root, max_file_size=max_file_size, available_languages=avail)

    build_ctx = build_graph(walk_result)
    resolve(build_ctx)
    community_count = assign_communities(build_ctx.graph)

    return PipelineResult(
        root=root,
        walk_result=walk_result,
        build_ctx=build_ctx,
        community_count=community_count,
        language_warnings=language_warnings,
    )

def _candidate_exists(file_paths: set[str | None], *candidates: str) -> str | None:
    for c in candidates:
        if c in file_paths:
            return c
    return None

def _resolve_call(
    ctx: BuildContext,
    call: PendingCall,
    class_methods: dict[str, dict[str, str]],
) -> None:
    target_id: str | None = None

    if call.receiver in _SELF_RECEIVERS and call.enclosing_class_id:
        target_id = class_methods.get(call.enclosing_class_id, {}).get(call.call_name)

    if target_id is None and call.receiver is None:
        symbol_index = ctx.file_symbol_index.get(call.importing_file_rel, {})
        candidate = symbol_index.get(call.call_name)
        if candidate is not None:
            node = ctx.graph.nodes.get(candidate)
            if node is not None and node.kind in (FUNCTION, METHOD, CLASS):
                target_id = candidate

    if target_id is not None:
        edge = GraphEdge(source=call.source_id, target=target_id, kind=CALLS, resolved=True)
    else:
        external_name = f"{call.receiver}.{call.call_name}" if call.receiver else call.call_name
        external = ctx.graph.get_or_create_external(external_name)
        edge = GraphEdge(source=call.source_id, target=external.id, kind=CALLS, resolved=False)
    ctx.graph.add_edge(edge)

def _resolve_js_import(imp: PendingImport, file_paths: set[str | None]) -> str | None:
    text = imp.path_text
    if not text.startswith("."):
        return None
    importing_dir = PurePosixPath(imp.importing_file_rel).parent
    base = (importing_dir / text).as_posix()
    base = str(PurePosixPath(base))

    candidates = [base] if PurePosixPath(base).suffix else []
    for suffix in _JS_SUFFIXES:
        candidates.append(f"{base}{suffix}")
    for suffix in _JS_SUFFIXES:
        candidates.append(f"{base}/index{suffix}")

    return _candidate_exists(file_paths, *candidates)

def _resolve_python_import(imp: PendingImport, file_paths: set[str | None]) -> str | None:
    text = imp.path_text
    importing_dir = PurePosixPath(imp.importing_file_rel).parent

    if text.startswith("."):
        dots = len(text) - len(text.lstrip("."))
        remainder = text[dots:]
        base = importing_dir
        for _ in range(dots - 1):
            base = base.parent
        module_path = base / remainder.replace(".", "/") if remainder else base
    else:
        module_path = PurePosixPath(text.replace(".", "/"))

    return _candidate_exists(
        file_paths,
        f"{module_path}.py",
        f"{module_path}/__init__.py",
    )

def _resolve_rust_import(imp: PendingImport, file_paths: set[str | None]) -> str | None:
    text = imp.path_text
    importing_dir = PurePosixPath(imp.importing_file_rel).parent

    if text.startswith("crate::") or text == "crate":
        remainder = text[len("crate::") :] if text != "crate" else ""
        base = PurePosixPath("src") / remainder.replace("::", "/") if remainder else PurePosixPath("src/lib")
    elif text.startswith("self::"):
        remainder = text[len("self::") :]
        base = importing_dir / remainder.replace("::", "/")
    elif text.startswith("super::"):
        remainder = text[len("super::") :]
        base = importing_dir.parent / remainder.replace("::", "/")
    else:
        return None

    return _candidate_exists(file_paths, f"{base}.rs", f"{base}/mod.rs")

def _resolve_import(ctx: BuildContext, imp: PendingImport, file_paths: set[str | None]) -> None:
    target_rel: str | None = None

    if imp.language == "python":
        target_rel = _resolve_python_import(imp, file_paths)
    elif imp.language in ("javascript", "typescript", "tsx"):
        target_rel = _resolve_js_import(imp, file_paths)
    elif imp.language == "rust":
        target_rel = _resolve_rust_import(imp, file_paths)
    elif imp.language in ("java", "kotlin"):
        target_rel = _resolve_dotted_suffix_import(imp, file_paths)
    # go, csharp, swift: left external in this MVP (see module docstring)

    if target_rel is not None:
        edge = GraphEdge(source=imp.source_id, target=f"file:{target_rel}", kind=IMPORTS, resolved=True)
    else:
        external = ctx.graph.get_or_create_external(imp.path_text)
        edge = GraphEdge(source=imp.source_id, target=external.id, kind=IMPORTS, resolved=False)
    ctx.graph.add_edge(edge)

def resolve(ctx: BuildContext) -> None:
    file_paths = {node.file_path for node in ctx.graph.nodes.values() if node.kind == FILE}
    class_methods: dict[str, dict[str, str]] = {}
    for node in ctx.graph.nodes.values():
        if node.kind == METHOD and node.parent_id:
            class_methods.setdefault(node.parent_id, {})[node.name] = node.id

    for imp in ctx.pending_imports:
        _resolve_import(ctx, imp, file_paths)

    for call in ctx.pending_calls:
        _resolve_call(ctx, call, class_methods)

def _load_spec(lang_id: str) -> LanguageSpec:
    if lang_id not in _GRAMMAR_SOURCES:
        raise ValueError(f"Unknown language id: {lang_id}")

    module_name, attr_name = _GRAMMAR_SOURCES[lang_id]
    module = importlib.import_module(module_name)
    getter = getattr(module, attr_name)
    language = ts.Language(getter())

    query_filename = _QUERY_FILES[lang_id]
    query_text = (
        importlib.resources.files(QUERIES_PACKAGE).joinpath(query_filename).read_text(encoding="utf-8")
    )
    query = ts.Query(language, query_text)

    return LanguageSpec(id=lang_id, language=language, query=query)

def available_languages() -> dict[str, str | None]:
    """Return {language_id: None} for loadable languages, {language_id: error} otherwise."""
    result: dict[str, str | None] = {}
    for lang_id in _GRAMMAR_SOURCES:
        try:
            _load_spec(lang_id)
            result[lang_id] = None
        except Exception as exc:  # noqa: BLE001 - want to record any load failure
            result[lang_id] = str(exc)
    return result

def get_spec(lang_id: str) -> LanguageSpec | None:
    """Return the LanguageSpec for lang_id, or None if unavailable (missing grammar/query)."""
    try:
        return _load_spec(lang_id)
    except Exception:  # noqa: BLE001
        return None

def atomic_write_bytes(path: Path, data: bytes) -> None:
    tmp_path = path.with_name(f"{path.name}.tmp-{os.getpid()}")
    try:
        tmp_path.write_bytes(data)
        os.replace(tmp_path, path)
    except BaseException:
        tmp_path.unlink(missing_ok=True)
        raise

def _community_color(community_id: int) -> dict[str, str]:
    hue = (community_id * 0.618033988749895) % 1.0
    r, g, b = colorsys.hsv_to_rgb(hue, 0.6, 0.9)
    background = f"#{int(r * 255):02x}{int(g * 255):02x}{int(b * 255):02x}"
    return {"background": background, "border": "#f8fafc"}

def _legend_html() -> str:
    return "".join(
        _LEGEND_ITEM.format(color=_KIND_COLORS[kind]["background"], label=label, kind=kind)
        for kind, label in _KIND_LABELS
    )

def _node_color(kind: str, community_id: int | None) -> dict[str, str]:
    if kind in _CLUSTERABLE_KINDS and community_id is not None:
        return _community_color(community_id)
    return _KIND_COLORS.get(kind, {"background": "#3b82f6", "border": "#60a5fa"})

def _build_vis_data(graph: CodeGraph) -> dict:
    nodes = []
    for node in graph.nodes.values():
        color = _node_color(node.kind, node.community_id)
        nodes.append(
            {
                "id": node.id,
                "label": node.name,
                "kind": node.kind,
                "qualified_name": node.qualified_name,
                "file_path": node.file_path,
                "start_line": node.start_line,
                "end_line": node.end_line,
                "snippet": node.snippet,
                "community_id": node.community_id,
                "color": {
                    "background": color["background"],
                    "border": color["border"],
                    "highlight": {"background": color["background"], "border": "#f8fafc"},
                    "hover": {"background": color["background"], "border": "#f8fafc"},
                },
            }
        )

    edges = []
    for edge in graph.edges:
        if edge.kind == CONTAINS:
            continue
        edges.append(
            {
                "from": edge.source,
                "to": edge.target,
                "kind": edge.kind,
                "color": {"color": _EDGE_COLORS.get(edge.kind, "#64748b"), "opacity": 0.5},
            }
        )

    return {"nodes": nodes, "edges": edges}

def to_cytoscape_elements(graph: CodeGraph) -> dict:
    nodes = []
    for node in graph.nodes.values():
        data = {
            "id": node.id,
            "label": node.name,
            "kind": node.kind,
            "qualified_name": node.qualified_name,
            "file_path": node.file_path,
            "language": node.language,
            "start_line": node.start_line,
            "end_line": node.end_line,
            "external": node.external,
            "snippet": node.snippet,
            "community_id": node.community_id,
        }
        if node.parent_id:
            data["parent"] = node.parent_id
        nodes.append({"data": data})

    edges = []
    for i, edge in enumerate(graph.edges):
        edges.append(
            {
                "data": {
                    "id": f"e{i}",
                    "source": edge.source,
                    "target": edge.target,
                    "kind": edge.kind,
                    "resolved": edge.resolved,
                }
            }
        )

    return {"nodes": nodes, "edges": edges}

def ensure_docs_dir(root: Path) -> Path:
    """Ensure `.buddhi/docs/` exists under root; return it."""
    docs_dir = root / BUDDHI_DIR_NAME / DOCS_DIR_NAME
    try:
        docs_dir.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise BuddhiFsError(f"could not prepare {docs_dir}: {exc}") from exc
    return docs_dir

def test_extract_definitions_for_language(language: str) -> None:
